<script setup>
import{ref,reactive,onMounted}from'vue';import{getProfile,updateProfile}from'../api';import{ElMessage}from'element-plus'
const data=ref(null),form=reactive({displayName:'',email:'',avatar:''})
async function load(){data.value=(await getProfile()).data;Object.assign(form,{displayName:data.value.displayName,email:data.value.email,avatar:data.value.avatar||''})}
async function save(){try{data.value=(await updateProfile(form)).data;const old=JSON.parse(localStorage.getItem('craft-user')||'{}');localStorage.setItem('craft-user',JSON.stringify({...old,displayName:data.value.displayName,email:data.value.email,avatar:data.value.avatar}));ElMessage.success('个人资料已保存')}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}
onMounted(load)
</script>
<template><section class="page-hero"><div class="container"><h1>个人中心</h1><p>维护账号资料，并查看你的收藏、定制需求与订单概况。</p></div></section><section class="section" v-if="data"><div class="container profile-grid"><div class="panel profile-card"><div class="profile-avatar"><img :src="data.avatar"/><div><div class="eyebrow">CUSTOMER ACCOUNT</div><h2>{{data.displayName}}</h2><p>@{{data.username}} · 普通客户</p></div></div><div class="profile-metrics"><div><b>{{data.favorites}}</b><small>收藏作品</small></div><div><b>{{data.requests}}</b><small>定制需求</small></div><div><b>{{data.orders}}</b><small>定制订单</small></div></div><div class="account-note">账号创建于 {{String(data.createdAt||'').replace('T',' ').slice(0,16)}}</div></div><div class="panel"><h3>编辑资料</h3><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.displayName" size="large"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" size="large"/></el-form-item><el-form-item label="头像地址"><el-input v-model="form.avatar" size="large" placeholder="可填写图片 URL"/></el-form-item></el-form><button class="primary-btn" @click="save">保存资料</button></div></div></section></template>